(function () {
      const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      const canvas = document.getElementById("webgl-canvas");
      const width = window.innerWidth || 1280;
      const height = window.innerHeight || 720;

      // Renderer setup
      const renderer = new THREE.WebGLRenderer({
        canvas: canvas,
        antialias: true,
        alpha: false,
        powerPreference: "high-performance"
      });
      renderer.setSize(width, height);
      renderer.setPixelRatio(1.0);
      renderer.setClearColor(0x0B192C, 1.0);

      // Scene and Camera
      const scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0B192C);

      const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
      camera.position.set(0, 3, 10);
      camera.lookAt(0, 0, 0);

      // Lighting
      const ambientLight = new THREE.AmbientLight(0x1E3E62, 1.5);
      scene.add(ambientLight);

      const dirLight = new THREE.DirectionalLight(0xF1F6F9, 1.8);
      dirLight.position.set(5, 10, 7);
      scene.add(dirLight);

      // Wave Geometry and Material
      const gridX = 40;
      const gridY = 40;
      const geometry = new THREE.PlaneGeometry(16, 16, gridX, gridY);
      geometry.rotateX(-Math.PI / 2.5);

      const material = new THREE.MeshStandardMaterial({
        color: 0x1E3E62,
        roughness: 0.35,
        metalness: 0.2,
        wireframe: false,
        flatShading: true
      });

      const waveMesh = new THREE.Mesh(geometry, material);
      waveMesh.position.set(0, -1, 0);
      scene.add(waveMesh);

      // Background geometric ring accent
      const ringGeo = new THREE.TorusGeometry(4.5, 0.08, 16, 64);
      const ringMat = new THREE.MeshBasicMaterial({ color: 0xF1F6F9, wireframe: true });
      const ringMesh = new THREE.Mesh(ringGeo, ringMat);
      ringMesh.position.set(0, 0.5, -3);
      scene.add(ringMesh);

      const posAttribute = geometry.attributes.position;
      const originalZ = new Float32Array(posAttribute.count);
      for (let i = 0; i < posAttribute.count; i++) {
        originalZ[i] = posAttribute.getZ(i);
      }

      // Timing and motion configuration
      const introDurationMs = 1800; // Motion budget [1200, 2400]
      let startTime = null;
      let mouseX = 0;
      let mouseY = 0;
      let targetTiltX = 0;
      let targetTiltY = 0;

      // Hover interaction
      window.addEventListener("mousemove", function (e) {
        const nx = (e.clientX / window.innerWidth) * 2 - 1;
        const ny = -(e.clientY / window.innerHeight) * 2 + 1;
        targetTiltX = ny * 0.15;
        targetTiltY = nx * 0.25;
      });

      function easeInOutQuad(t) {
        return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
      }

      function animate(now) {
        requestAnimationFrame(animate);

        if (startTime === null) startTime = now;
        const elapsed = now - startTime;
        const progress = prefersReducedMotion ? 1.0 : Math.min(1.0, elapsed / introDurationMs);
        const introFactor = easeInOutQuad(progress);

        // Smooth wave undulation
        const timeSec = prefersReducedMotion ? 0 : now * 0.001;
        for (let i = 0; i < posAttribute.count; i++) {
          const u = (i % (gridX + 1)) / gridX;
          const v = Math.floor(i / (gridX + 1)) / gridY;
          const wave1 = Math.sin(u * 5.0 + timeSec * 1.5) * 0.45;
          const wave2 = Math.cos(v * 4.0 + timeSec * 1.2) * 0.35;
          const elevation = (wave1 + wave2) * introFactor;
          posAttribute.setZ(i, originalZ[i] + elevation);
        }
        posAttribute.needsUpdate = true;
        geometry.computeVertexNormals();

        // Tilt response
        mouseX += (targetTiltX - mouseX) * 0.05;
        mouseY += (targetTiltY - mouseY) * 0.05;
        waveMesh.rotation.z = mouseY * 0.5;
        waveMesh.rotation.x = mouseX * 0.5;
        ringMesh.rotation.z = timeSec * 0.2;

        renderer.render(scene, camera);
      }

      // Initial frame trigger
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    })();
